if EnableMod then

	function addToList(list, addition)
		local templist = TweakDB:GetFlat(list)
		if type(templist) ~= "table" then
			local dot = string.find(list, "%.[^%.]*$")
			local recName = dot and string.sub(list, 1, dot - 1) or nil
			if recName and TweakDB:GetRecord(recName) ~= nil and templist == nil then
				templist = {}
			else
				return
			end
		end
		for _, v in ipairs(templist) do
			if v == addition then
				return
			end
		end
		table.insert(templist, addition)
		TweakDB:SetFlat(list, templist)
	end

	function createConstantStatModifier(recordName, modifierType, statType, value)
		TweakDB:CreateRecord(recordName, "gamedataConstantStatModifier_Record")
		TweakDB:SetFlatNoUpdate(recordName..".modifierType", modifierType)
		TweakDB:SetFlatNoUpdate(recordName..".statType", statType)
		TweakDB:SetFlatNoUpdate(recordName..".value", value)
		TweakDB:Update(recordName)
	end


	function createEquipmentWeaponGrp(name, weapon, minlvl, weight, dual, left)
		if dual == true then
			TweakDB:CloneRecord(name..left.."EquipItemLeft", "Character.ValentinosPrimaryHandgunDualPool_inline5")
			TweakDB:CloneRecord(name..weapon.."EquipItemRight", "Character.ValentinosPrimaryHandgunDualPool_inline4")
			TweakDB:SetFlat(name..left.."EquipItemLeft"..".item", left)
			TweakDB:SetFlat(name..weapon.."EquipItemRight"..".item", weapon)

			TweakDB:CloneRecord(name.."EquipItemPoolEntry", "Character.ValentinosPrimaryHandgunDualPool_inline3")
			TweakDB:SetFlat(name.."EquipItemPoolEntry"..".items", {name..left.."EquipItemLeft", name..weapon.."EquipItemRight"})
			TweakDB:SetFlat(name.."EquipItemPoolEntry"..".minLevel", minlvl)
			TweakDB:SetFlat(name.."EquipItemPoolEntry"..".weight", weight)
		else
			TweakDB:CloneRecord(name..weapon.."EquipItemRight", "Character.ValentinosPrimaryHandgunDualPool_inline4")
			TweakDB:SetFlat(name..weapon.."EquipItemRight"..".item", weapon)

			TweakDB:CloneRecord(name.."EquipItemPoolEntry", "Character.ValentinosPrimaryHandgunDualPool_inline3")
			TweakDB:SetFlat(name.."EquipItemPoolEntry"..".items", {name..weapon.."EquipItemRight"})
			TweakDB:SetFlat(name.."EquipItemPoolEntry"..".minLevel", minlvl)
			TweakDB:SetFlat(name.."EquipItemPoolEntry"..".weight", weight)
		end
		TweakDB:CloneRecord(name.."EquipItemPool", "Character.valentinos_elite2_ranged3_dual_ma_rare_inline1")
		TweakDB:SetFlat(name.."EquipItemPool"..".pool", {name.."EquipItemPoolEntry"})

		TweakDB:CloneRecord(name.."EquipGrp", "Character.valentinos_elite2_ranged3_dual_ma_rare_inline0")
		TweakDB:SetFlat(name.."EquipGrp"..".equipmentItems", {name.."EquipItemPool"})
	end















