	function createAbilityGrp(abilitygrpname, operator, stat, value)
		TweakDB:CreateRecord(abilitygrpname.."Ability", "gamedataGameplayAbility_Record")
		TweakDB:CreateRecord(abilitygrpname.."AbilityLogic", "gamedataGameplayLogicPackage_Record")
		TweakDB:SetFlat(abilitygrpname.."Ability"..".abilityPackage", abilitygrpname.."AbilityLogic")
		createConstantStatModifier(abilitygrpname.."Stat", operator, stat, value)
		TweakDB:SetFlat(abilitygrpname.."AbilityLogic"..".stats", {abilitygrpname.."Stat"})
		TweakDB:CreateRecord(abilitygrpname.."AbilityGrp", "gamedataGameplayAbilityGroup_Record")
		addToList(abilitygrpname.."AbilityGrp"..".abilities", abilitygrpname.."Ability")
	end

