	function createPreventionUnit(templatename, vehicletemplate)
		TweakDB:CloneRecord(templatename.."Prevention", templatename)
		TweakDB:SetFlat(templatename.."Prevention"..".baseAttitudeGroup", TweakDB:GetFlat("Character.prevention_police_handgun_ma.baseAttitudeGroup"))
		TweakDB:SetFlat(templatename.."Prevention"..".reactionPreset", TweakDB:GetFlat("Character.prevention_police_handgun_ma.reactionPreset"))
		TweakDB:SetFlat(templatename.."Prevention"..".sensePreset", TweakDB:GetFlat("Character.prevention_police_handgun_ma.sensePreset"))
		TweakDB:SetFlat(templatename.."Prevention"..".squadParamsID", TweakDB:GetFlat("Character.prevention_police_handgun_ma.squadParamsID"))
		addToList(templatename.."Prevention"..".tags", "InActivePoliceChase")
		TweakDB:SetFlat(templatename.."Prevention"..".threatTrackingPreset", TweakDB:GetFlat("Character.prevention_police_handgun_ma.threatTrackingPreset"))
		TweakDB:CloneRecord(vehicletemplate.."_"..templatename, vehicletemplate)
		TweakDB:SetFlat(vehicletemplate.."_"..templatename..".preventionPassengers", {templatename.."Prevention"})
	end

