	end


	TweakDB:CloneRecord("CoverGrenadeSelector", "CoverActions.CoverThrowGrenadeSelector")
	TweakDB:SetFlat("CoverGrenadeSelector.actions", {"CoverActions.ThrowGrenadeCoverCutting", "CoverActions.ThrowGrenadeCoverEMP", "CoverActions.ThrowGrenadeCoverIncendiary", "CoverActions.ThrowGrenadeCoverBiohazard", "CoverActions.ThrowGrenadeCoverFrag", "CoverActions.ThrowGrenadeCoverFlash", "CoverActions.ThrowGrenadeCoverSmokeNear", "CoverActions.ThrowGrenadeCoverSmoke", "CoverActions.ThrowGrenadeCoverRecon"})

	TweakDB:CloneRecord("CommandCoverGrenadeSelector", "CoverActions.CoverThrowGrenadeSelector")
	TweakDB:SetFlat("CommandCoverGrenadeSelector.actions", {"CoverActions.CommandThrowGrenadeCoverCutting", "CoverActions.CommandThrowGrenadeCoverEMP", "CoverActions.CommandThrowGrenadeCoverIncendiary", "CoverActions.CommandThrowGrenadeCoverBiohazard", "CoverActions.CommandThrowGrenadeCoverFrag", "CoverActions.CommandThrowGrenadeCoverFlash", "CoverActions.ThrowGrenadeCoverSmokeNear", "CoverActions.ThrowGrenadeCoverSmoke", "CoverActions.CommandThrowGrenadeCoverRecor"})

	function setCOND(item, conditions, reverse)
		if reverse == true then
			TweakDB:CloneRecord(item.."OR", "CoverActions.CommandCoverThrowGrenadeSelector_inline1")
			TweakDB:SetFlat(item.."OR"..".OR", conditions)
			TweakDB:CloneRecord(item.."COND", "CoverActions.CoverThrowGrenadeSelector_inline0")
			TweakDB:SetFlat(item.."COND"..".condition", item.."OR")
			TweakDB:SetFlat(item..".activationCondition", item.."COND")
		else
			TweakDB:CloneRecord(item.."AND", "Condition.CoverThrowGrenadeSelectorCondition")
			TweakDB:SetFlat(item.."AND"..".AND", conditions)
			TweakDB:CloneRecord(item.."COND", "CoverActions.CoverThrowGrenadeSelector_inline0")
			TweakDB:SetFlat(item.."COND"..".condition", item.."AND")
			TweakDB:SetFlat(item..".activationCondition", item.."COND")
		end
	end


	function createSequence(sequencename, sequenceAND, actions, reverse)
		TweakDB:CloneRecord(sequencename, "ActionSamples.ShootSequence")
		setCOND(sequencename, sequenceAND)
		TweakDB:SetFlat(sequencename..".actions", actions)
	end

	function createSelector(selectorname, selectorAND, actions, reverse)
		TweakDB:CloneRecord(selectorname, "CoverActions.CoverDecisionSelector")
		setCOND(selectorname, selectorAND, reverse)
		TweakDB:SetFlat(selectorname..".actions", actions)
	end

	function createCondition(name, conditions, reverse)
		if reverse == true then
			TweakDB:CloneRecord(name.."OR", "CoverActions.CommandCoverThrowGrenadeSelector_inline1")
			TweakDB:SetFlat(name.."OR"..".OR", conditions)
			TweakDB:CloneRecord(name.."COND", "CoverActions.CoverThrowGrenadeSelector_inline0")
			TweakDB:SetFlat(name.."COND"..".condition", name.."OR")
		else
			TweakDB:CloneRecord(name.."AND", "Condition.CoverThrowGrenadeSelectorCondition")
			TweakDB:SetFlat(name.."AND"..".AND", conditions)
			TweakDB:CloneRecord(name.."COND", "CoverActions.CoverThrowGrenadeSelector_inline0")
			TweakDB:SetFlat(name.."COND"..".condition", name.."AND")
		end
	end

