	function createStatusEffect(effectname, effecttocopy, sfx, vfx, durationlength, gameplayTags, packageEffectors, packageStats)
		TweakDB:CloneRecord(effectname, effecttocopy)
		local sfxlist = {}
		local vfxlist = {}
		for i,v in ipairs(sfx) do
			TweakDB:CloneRecord(effectname.."_sfx_"..v, "Oda.OverHeatVFX_inline2")
			TweakDB:SetFlat(effectname.."_sfx_"..v..".name", v)
			table.insert(sfxlist, effectname.."_sfx_"..v)
			
		end
		for i,v in ipairs(vfx) do
			TweakDB:CloneRecord(effectname.."_vfx_"..v, "Oda.OverHeatVFX_inline2")
			TweakDB:SetFlat(effectname.."_vfx_"..v..".name", v)
			table.insert(vfxlist, effectname.."_vfx_"..v)
		end
		TweakDB:SetFlat(effectname..".SFX", sfxlist)
		TweakDB:SetFlat(effectname..".VFX", vfxlist)

		TweakDB:CloneRecord(effectname.."durationStatGrp", "AIQuickHackStatusEffect.BaseBuffQuickhack_inline0")
		createConstantStatModifier(effectname.."durationStat", "Additive", "BaseStats.MaxDuration", durationlength)
		TweakDB:SetFlat(effectname.."durationStatGrp"..".statModifiers", {effectname.."durationStat"})
		TweakDB:SetFlat(effectname..".duration", effectname.."durationStatGrp")

		TweakDB:SetFlat(effectname..".gameplayTags", gameplayTags or {})

		TweakDB:CloneRecord(effectname.."package", "AIQuickHackStatusEffect.QuickHack_GLP")
		TweakDB:SetFlat(effectname.."package"..".effectors", packageEffectors)
		TweakDB:SetFlat(effectname.."package"..".stats", packageStats)
		TweakDB:SetFlat(effectname..".packages", {effectname.."package"})

	end

