		createConstantStatModifier(name.."uploadDurationStat", "Additive", "BaseStats.QuickHackUpload", uploadDuration)
		TweakDB:CloneRecord(name.."ObjectAction", "AIQuickHack.HackDeath_VeryHard")
		TweakDB:SetFlat(name.."ObjectAction"..".activationTime", {"AIQuickHack.AIQuickHack_inline3", name.."uploadDurationStat"})
		TweakDB:SetFlat(name.."ObjectAction"..".completionEffects", {name.."ObjectActionEffect"})
		TweakDB:SetFlat(name.."ObjectAction"..".objectActionUI", actionUI)

		TweakDB:CloneRecord(name.."SubAction", "NetrunnerActions.HackOverload_inline4")
