	function createStatusEffectSubAction(name, delay, statusEffects, target, isApply)
		TweakDB:CloneRecord(name.."StatusEffectSubAction", "AbilityActions.BerserkActivation_inline4")
		TweakDB:SetFlat(name.."StatusEffectSubAction"..".delay", delay)
		TweakDB:SetFlat(name.."StatusEffectSubAction"..".statusEffects", statusEffects)
		TweakDB:SetFlat(name.."StatusEffectSubAction"..".target", target)
		if isApply == true then
			TweakDB:SetFlat(name.."StatusEffectSubAction"..".apply", true)
		else
			TweakDB:SetFlat(name.."StatusEffectSubAction"..".apply", false)
			TweakDB:SetFlat(name.."StatusEffectSubAction"..".remove", true)
		end
	end





