	function createReflectQuickhackAction(name, subAction, effectList)
		TweakDB:CloneRecord(name.."ReflectQuickhackAction", "ReflectOverloadQuickhackAction")
		TweakDB:SetFlat(name.."ReflectQuickhackAction"..".loopSubActions", {"NetrunnerActions.HackAction_inline2", "NetrunnerActions.HackAction_inline3", subAction})
		effectListTemp = {}
		for i,v in ipairs(effectList) do
			TweakDB:CloneRecord(name..v.."ReflectEffectCOND", "Condition.StatusEffectEMP")
			TweakDB:SetFlat(name..v.."ReflectEffectCOND"..".statusEffect", v)
			table.insert(effectListTemp, name..v.."ReflectEffectCOND")
		end
		--TweakDB:CloneRecord(name.."ReflectEffectCOND", "ReflectOverloadEffectCOND")
		--TweakDB:SetFlat(name.."ReflectEffectCOND.statusEffect", effectname)
		--TweakDB:SetFlat(name.."ReflectEffectCOND.statusEffectType", effectType)
		--TweakDB:SetFlat(name.."ReflectEffectCOND.gameplayTag", effectTag)
		createCondition(name.."ReflectQuickhackAction".."OR", effectListTemp, true)
		setCOND(name.."ReflectQuickhackAction", {name.."ReflectQuickhackAction".."OR".."OR"}, false)
		addToList(name.."ReflectQuickhackAction".."AND"..".AND", "Condition.CombatTarget")
		addToList(name.."ReflectQuickhackAction".."AND"..".AND", "HasBoostCortexCOND")
		addToList(name.."ReflectQuickhackAction".."AND"..".AND", "Condition.InStatesCombat")
	end

