	function replaceDodgeSelector(selectorname, composite, selectoractions)
		local weaponList = {"Fist", "Hammer", "Katana", "Knife", "MantisBlades", "OneHanded"}
		for i,v in ipairs(weaponList) do
			local weapon = v
			local weaponActionList = {}
			for i,v in ipairs(selectoractions) do
				local actionname = v
				table.insert(weaponActionList, "Melee"..weapon.."Actions".."."..actionname)
			end
			createSelector(v..selectorname, {}, weaponActionList, false)
			TweakDB:SetFlat(v..selectorname..".defaultAction", "Melee"..weapon.."Actions".."."..selectoractions[1])

			if weapon == "Fist" then
				TweakDB:SetFlat("Corpo_".."Fists".."."..composite..".nodes", {weapon..selectorname})
				TweakDB:SetFlat("Gang_".."Fists".."."..composite..".nodes", {weapon..selectorname})
			elseif weapon == "OneHanded" then
				TweakDB:SetFlat("Corpo_".."OneHandedClub".."."..composite..".nodes", {weapon..selectorname})
				TweakDB:SetFlat("Gang_".."OneHandedClub".."."..composite..".nodes", {weapon..selectorname})
			else
				TweakDB:SetFlat("Corpo_"..v.."."..composite..".nodes", {weapon..selectorname})
				TweakDB:SetFlat("Gang_"..v.."."..composite..".nodes", {weapon..selectorname})
			end
		end
	end

	KerenBulletDodgeActions = {"DodgeKerenzikovLeftOnSpotDefinition", "DodgeKerenzikovRightOnSpotDefinition", "DodgeKerenzikovLeftFrontDefinition", "DodgeKerenzikovRightFrontDefinition", "DodgeKerenzikovBackDefinition"}
