	function createCooldownAction(actionname, cooldownname, cooldownduration)
		TweakDB:CloneRecord(actionname.."Cooldown", "KurtKrauserBoss.PowerfulMeleeAttackCooldown")
		TweakDB:SetFlat(actionname.."Cooldown"..".duration", cooldownduration)
		TweakDB:SetFlat(actionname.."Cooldown"..".name", cooldownname)

		TweakDB:CloneRecord(actionname.."CooldownConditionAction", "KurtKrauserBoss.PowerfulMeleeAttackCooldownCondition")
		TweakDB:SetFlat(actionname.."CooldownConditionAction"..".cooldowns", {actionname.."Cooldown"})

		TweakDB:CloneRecord(actionname.."StartCooldownSubAction", "KurtKrauserBoss.SetPowerfulMeleeAttackCooldown_inline1")
		TweakDB:SetFlat(actionname.."StartCooldownSubAction"..".cooldowns", {actionname.."Cooldown"})

		TweakDB:CloneRecord(actionname.."StartCooldownAction", "KurtKrauserBoss.PowerfulMeleeAttackCooldownCondition")
		TweakDB:SetFlat(actionname.."StartCooldownAction"..".cooldowns", {})
		TweakDB:SetFlat(actionname.."StartCooldownAction"..".subActions", {actionname.."StartCooldownSubAction"})
	end


