	CombosToAddWeaponList = {"Fists", "Hammer", "Katana", "Knife", "LongBlade", "MantisBlades", "OneHandedClub", "TwoHandedClub"}
	function addConsumableAndBerserkSelector(CombosToAddList, CombosToAddWeaponList)
		for i,v in ipairs(CombosToAddList) do
			local combo = v
			for i,v in ipairs(CombosToAddWeaponList) do
				addToList("Corpo_"..v.."."..combo..".nodes", "ConsumableSelector")
				addToList("Corpo_"..v.."."..combo..".nodes", "BerserkActivationAction")
				addToList("Corpo_"..v.."."..combo..".nodes", "MeleeChameleonActivateAction")
				addToList("Gang_"..v.."."..combo..".nodes", "ConsumableSelector")
				addToList("Gang_"..v.."."..combo..".nodes", "BerserkActivationAction")
				addToList("Gang_"..v.."."..combo..".nodes", "MeleeChameleonActivateAction")
			end
		end
	end
	addConsumableAndBerserkSelector(CombosToAddList, CombosToAddWeaponList)
	






