	function setArchetypeData(name, abilityGroups, shootingPatternPackages, statModifierGroups, archetypeType, isCreateNew)
		if isCreateNew == true then
			TweakDB:CloneRecord(name.."ArchetypeData", "ArchetypeData.AndroidMeleeT1")
			TweakDB:SetFlat(name.."ArchetypeData"..".abilityGroups", abilityGroups)
			TweakDB:SetFlat(name.."ArchetypeData"..".shootingPatternPackages", shootingPatternPackages)
			TweakDB:SetFlat(name.."ArchetypeData"..".statModifierGroups", statModifierGroups)
			TweakDB:SetFlat(name.."ArchetypeData"..".type", archetypeType)
		else
			TweakDB:SetFlat(name..".abilityGroups", abilityGroups)
			TweakDB:SetFlat(name..".shootingPatternPackages", shootingPatternPackages)
			TweakDB:SetFlat(name..".statModifierGroups", statModifierGroups)
			TweakDB:SetFlat(name..".type", archetypeType)
		end
	end

	function createStatModifierGrp(name, statModifiers)
		TweakDB:CloneRecord(name.."StatModifierGrp", "ArchetypeData.NetrunnerT2_inline0")
		TweakDB:SetFlat(name.."StatModifierGrp"..".statModifiers", statModifiers)
	end





