	function createRangedAttackPackage(name, projectile)
		TweakDB:CloneRecord(name.."RangedAttack", "Attacks.ExplodingBullet")
		TweakDB:SetFlat(name.."RangedAttack"..".NPCAttack", projectile)
		TweakDB:SetFlat(name.."RangedAttack"..".NPCTimeDilated", projectile)
		TweakDB:SetFlat(name.."RangedAttack"..".playerAttack", projectile)
		TweakDB:SetFlat(name.."RangedAttack"..".playerTimeDilated", projectile)
		TweakDB:SetFlat(name.."RangedAttack"..".secondaryPlayerAttack", projectile)
		TweakDB:SetFlat(name.."RangedAttack"..".secondaryPlayerTimeDilated", projectile)

		TweakDB:CloneRecord(name.."RangedAttackPackage", "Attacks.ExplodingBulletPackage")
		TweakDB:SetFlat(name.."RangedAttackPackage"..".chargeFire", name.."RangedAttack")
		TweakDB:SetFlat(name.."RangedAttackPackage"..".defaultFire", name.."RangedAttack")
	end


