	function createComposite(name, nodes)
		TweakDB:CloneRecord(name, "OdaBoss.BossInvestigateCustomComposite")
		TweakDB:SetFlat(name..".nodes", nodes)
	end

	function createSequence(name, actions)
		TweakDB:CloneRecord(name, "OdaBoss.ActivateKerenzikovSequence")
		TweakDB:SetFlat(name..".actions", actions)
	end



