	function createRegenEffector(name, rangeBegin, rangeEnd, valuePerSec)
		TweakDB:CloneRecord(name.."PoolValueModifier", "BaseStatusEffect.CombatStim_inline7")
		TweakDB:SetFlat(name.."PoolValueModifier"..".rangeBegin", rangeBegin)
		TweakDB:SetFlat(name.."PoolValueModifier"..".rangeEnd", rangeEnd)
		TweakDB:SetFlat(name.."PoolValueModifier"..".valuePerSec", valuePerSec)

		TweakDB:CloneRecord(name.."ModifyStatPoolEffector", "BaseStatusEffect.CombatStim_inline6")
		TweakDB:SetFlat(name.."ModifyStatPoolEffector"..".poolModifier", name.."PoolValueModifier")
	end

