	function createAVPreventionUnit(templatename, vehicletemplate)
		TweakDB:CloneRecord(templatename.."Prevention", templatename)
		TweakDB:SetFlat(templatename.."Prevention"..".baseAttitudeGroup", TweakDB:GetFlat("Character.maxtac_av_LMG_mb_2nd_wave.baseAttitudeGroup"))
		TweakDB:SetFlat(templatename.."Prevention"..".priority", TweakDB:GetFlat("Character.prevention_maxtac_av_base.priority"))
		TweakDB:SetFlat(templatename.."Prevention"..".quest", TweakDB:GetFlat("Character.prevention_maxtac_av_base.quest"))
		TweakDB:SetFlat(templatename.."Prevention"..".contentAssignment", TweakDB:GetFlat("Character.prevention_maxtac_av_base.contentAssignment"))
		TweakDB:SetFlat(templatename.."Prevention"..".reactionPreset", TweakDB:GetFlat("Character.maxtac_av_LMG_mb_2nd_wave.reactionPreset"))
		TweakDB:SetFlat(templatename.."Prevention"..".sensePreset", TweakDB:GetFlat("Character.maxtac_av_LMG_mb_2nd_wave.sensePreset"))
		TweakDB:SetFlat(templatename.."Prevention"..".squadParamsID", TweakDB:GetFlat("Character.maxtac_av_LMG_mb_2nd_wave.squadParamsID"))
		addToList(templatename.."Prevention"..".tags", "InActivePoliceChase")
		addToList(templatename.."Prevention"..".tags", "MaxTac_Prevention")
		addToList(templatename.."Prevention"..".tags", "Cyberpsycho")
		addToList(templatename.."Prevention"..".tags", "allow_finisher_threshold")
		addToList(templatename.."Prevention"..".abilities", "Ability.IsAVMaxTac")
		TweakDB:SetFlat(templatename.."Prevention"..".threatTrackingPreset", TweakDB:GetFlat("Character.maxtac_av_LMG_mb_2nd_wave.threatTrackingPreset"))
		TweakDB:CloneRecord(vehicletemplate.."_"..templatename, vehicletemplate)
		TweakDB:SetFlat(vehicletemplate.."_"..templatename..".preventionPassengers", {templatename.."Prevention"})
	end

