	function createAnimWithPhase(name, animfeature, animvariation, animslot, phaseduration)
		TweakDB:CloneRecord(name.."AnimData", "SpecialActions.EnableBerserker_inline7")
		TweakDB:SetFlat(name.."AnimData"..".animFeature", animfeature)
		TweakDB:SetFlat(name.."AnimData"..".animSlot", animslot)
		TweakDB:SetFlat(name.."AnimData"..".animVariation", animvariation)

		TweakDB:CloneRecord(name.."LoopPhase", "AbilityActions.CannotUseBerserk_inline2")
		TweakDB:SetFlat(name.."LoopPhase"..".duration", phaseduration)

		TweakDB:CloneRecord(name.."Action", "AdamSmasherBoss.Stage1Condition")
		TweakDB:SetFlat(name.."Action"..".loop", name.."LoopPhase")
		TweakDB:SetFlat(name.."Action"..".animData", name.."AnimData")
		TweakDB:SetFlat(name.."Action"..".activationCondition", "")

	end


