	function newReplaceDodgeSelector(selectorname, composite, selectoractions)
		local weaponList = {"Fist", "Hammer", "Katana", "Knife", "MantisBlades", "OneHanded"}
		for i,v in ipairs(weaponList) do
			local weapon = v
			local weaponActionList = {}
			for i,v in ipairs(selectoractions) do
				local actionname = v
				table.insert(weaponActionList, "Melee"..weapon.."Actions".."."..actionname)
				TweakDB:SetFlat("Melee"..weapon.."Actions".."."..actionname..".tickets", {})
				--addToList("Melee"..weapon.."Actions".."."..actionname..".cooldowns", "NewMeleeDodgeCooldown")
			end
			--createSelector(v..selectorname, {}, weaponActionList, false)
			--TweakDB:SetFlat(v..selectorname..".defaultAction", "Melee"..weapon.."Actions".."."..selectoractions[1])

			if weapon == "Fist" then
				TweakDB:SetFlat("Corpo_".."Fists".."."..composite..".nodes", weaponActionList)
				TweakDB:SetFlat("Gang_".."Fists".."."..composite..".nodes", weaponActionList)
			elseif weapon == "OneHanded" then
				TweakDB:SetFlat("Corpo_".."OneHandedClub".."."..composite..".nodes", weaponActionList)
				TweakDB:SetFlat("Gang_".."OneHandedClub".."."..composite..".nodes", weaponActionList)
			else
				TweakDB:SetFlat("Corpo_"..v.."."..composite..".nodes", weaponActionList)
				TweakDB:SetFlat("Gang_"..v.."."..composite..".nodes", weaponActionList)
			end
		end
	end




